insert into species_def values ('sparra', 'Dummicub', 'Tamed: Spar with it while it is out with you: a swing teaches fighting, the weapon skill and body strength as a swing at a wild creature does, and wears the weapon as much; your blows stop at 50% of its health, where it yields until above it; never strikes back. Settlement task: spar with a guard of yours on the settlement, 1 at a time, the one that sparred longest ago first. Time per spar: the guard''s time per action, 37 seconds at level 1, 11 at level 100. Per spar: 1 blow each; guard body strength as per attack on a wild creature; Dummicub fighting as per spar swing of yours, learning 400% (27% when you spar it); 1 action of each one''s stamina. Blows stop at 50% of health, on both; a yielded one stands until above it. Level: fighting, learned per spar swing of yours that lands on it, learning 27%; per spar with a guard of yours on the settlement, learning 400%. Evolves at level 25: Dummibear.', 180, 0.8, 1.9, 6, 0.12, 'an apple or bread', true, null, 0, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, 'crush', null, null);
