insert into species_def values ('bura', 'Packlet', 'No settlement task. Panniers: 200 items, opened from its menu; a store within 3 tiles for crafting and building. Crate, release, cull: panniers empty only. Level: body strength, learned per 30 seconds out at your heel or keeping a settlement. Evolves at level 25: Haulbud.', 165, 2.4, 1.5, 1, 0.09, 'grass or grain', false, null, 6, 4, false, false, false, false, false, false, false, false, false, false, true, false, null, null, null, null, 'crush', null, null);
