insert into species_def values ('vesp', 'Buzzlet', 'Settlement task: the nearest hive with room within its reach of the totem. Per go: one wildflower tile within 3 tiles of the hive, in turn, and back. Honey into the hive: a honey per 50 hours worked per wildflower clump within 3 tiles, as a skep there; a beeswax per 4 honey; none in winter. Defends it. Level: animal husbandry. Evolves at level 25: Combworker.', 36, 1.2, 2.4, 1, 0.1, 'berries or honey', false, 'hive', 8, 4, false, false, false, false, false, false, false, false, false, false, true, false, null, null, null, null, 'pierce', null, null);
