insert into species_def values ('millhog', 'Millhog', 'Hybrid: Wheatley × Pigroot. Tasks: grind wheat and corn and press olives in your settlement stores; sow, tend and harvest fields. Order: milling first, farming when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of milling and farming. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 60, 1, 2.1, 14, 0, 'grain or bread', true, 'mill', 8, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
