insert into species_def values ('bricklekiln', 'Bricklekiln', 'Hybrid: Kilnlet × Brickling. Tasks: load your kilns with unfired clay bricks, unfired clay bowls, unfired clay pots, unfired clay jars and unfired amphoras from your settlement stores and empty them; carry what planned building work wants from your settlement stores and fit it: walls and columns on their storey; floors, roofs, staircases and ladders from the storey under; bridge or aqueduct spans, foundations; storeys up by staircase, not ladder. Order: loading kilns first, hod carrying when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of pottery and masonry. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 93, 1.4, 1.65, 20, 0, 'a vegetable or bread', true, 'kiln', 12, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
