insert into species_def values ('emberbroth', 'Emberbroth', 'Hybrid: Emberkit × Brothlet. Tasks: rake ashes from your campfires, ovens, smelters and kilns into your settlement stores; leach ash and buckets of water from your settlement stores into lye; cook from your settlement stores at your lit campfires and ovens. Order: raking ashes first, cooking when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of alchemy and cooking. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 57, 0.8, 1.9, 16, 0, 'nuts or bread', true, 'ash', 8, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
