insert into species_def values ('sawchip', 'Sawchip', 'Hybrid: Chipkin × Logkit. Tasks: chisel rock shards in your settlement stores into stone brick, 2 a shard; saw logs in your settlement stores into planks, 3 a log. Order: chiselling stone brick first, sawing planks when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of stonecutting and carpentry. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 78, 1.2, 1.8, 16, 0, 'a vegetable or grass', true, 'chisel', 6, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
