insert into species_def values ('cindermortar', 'Cindermortar', 'Hybrid: Emberkit × Pestlet. Tasks: rake ashes from your campfires, ovens, smelters and kilns into your settlement stores; leach ash and buckets of water from your settlement stores into lye; mix concrete in your settlement stores, 1 mortar + 1 ashes: 1 concrete; output to your settlement stores. Order: raking ashes first, mixing concrete when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of alchemy and masonry. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 87, 2.2, 1.85, 28, 0, 'nuts or bread', true, 'ash', 10, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
