insert into species_def values ('lyepelt', 'Lyepelt', 'Hybrid: Peltling × Emberkit. Tasks: tan hides in your settlement stores with lye; rake ashes from your campfires, ovens, smelters and kilns into your settlement stores; leach ash and buckets of water from your settlement stores into lye. Order: tanning hides first, raking ashes when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of leatherworking and alchemy. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 60, 1, 2, 18, 0, 'a fish or an acorn', true, 'tan', 8, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, null, null, null);
