insert into species_def values ('curdchurn', 'Curdchurn', 'Hybrid: Creamlet × Wheybit. Tasks: churn butter at your butter churns, 1 bucket of milk: 4 butter + 1 bucket; output to your settlement stores; press cheese in your settlement stores, 1 bucket of milk: 3 cheese + 1 bucket of whey; output to your settlement stores. Order: churning butter first, pressing cheese when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: cooking. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 96, 2.8, 2, 30, 0, 'meat', false, 'churn', 10, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, 'cut', null, null);
