insert into species_def values ('shearwhey', 'Shearwhey', 'Hybrid: Wheybit × Shearling. Tasks: press cheese in your settlement stores, 1 bucket of milk: 3 cheese + 1 bucket of whey; output to your settlement stores; milk your Creamcalfs, Milkmeres and Lactisovereigns into empty buckets in your settlement stores; shear or pluck your others at 90% regrowth; output to your settlement stores. Order: pressing cheese first, milking and shearing when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of cooking and animal husbandry. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 78, 1.8, 2.05, 28, 0, 'meat', false, 'cheese', 10, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, 'bite', null, null);
