insert into species_def values ('shearspin', 'Shearspin', 'Hybrid: Sprindle × Shearling. Tasks: spin wool, cotton and wemp fibre in your settlement stores into yarn at your spindles, 2 yarn per 2 fibres; output to your settlement stores; milk your Creamcalfs, Milkmeres and Lactisovereigns into empty buckets in your settlement stores; shear or pluck your others at 90% regrowth; output to your settlement stores. Order: spinning yarn first, milking and shearing when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of tailoring and animal husbandry. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 81, 2.2, 2.15, 30, 0, 'meat', false, 'spin', 12, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, 'cut', null, null);
