insert into species_def values ('yarnkit', 'Yarnkit', 'Hybrid: Clothkit × Sprindle. Tasks: make bandages, healing covers and salves in your settlement stores, 1 cloth: 3 bandage; 2 herb + 1 cotton: 3 healing cover; 2 herb + 1 beeswax: 1 salve (herb: thyme, basil, mint, sage or rosemary); output to your settlement stores; spin wool, cotton and wemp fibre in your settlement stores into yarn at your spindles, 2 yarn per 2 fibres; output to your settlement stores. Order: making bandages, covers and salves first, spinning yarn when it has none in reach. Task speed: 75% of a pure-bred''s in each. Health +5%. Level: mean of first aid and tailoring. Stage: its less-evolved parent''s, for good. Infertile. Never wild.', 93, 3, 2.05, 30, 0, 'meat', false, 'bandage', 12, 4, false, false, false, false, false, false, false, false, false, false, false, false, null, null, null, null, 'pierce', null, null);
